package com.library.dao;
import com.library.enums.TransactionStatus; import com.library.model.Transaction; import com.library.util.DBConnection; import java.math.BigDecimal; import java.sql.*; import java.util.*;
public class TransactionDAO {
 private static final String BASE="SELECT t.*,b.book_name,u.name member_name FROM transactions t JOIN books b ON b.book_id=t.book_id JOIN member_details m ON m.member_id=t.member_id JOIN users u ON u.user_id=m.user_id ";
 public List<Transaction> findAll(String term){String sql=BASE+"WHERE CAST(t.transaction_id AS CHAR) LIKE ? OR CAST(t.member_id AS CHAR) LIKE ? OR CAST(t.book_id AS CHAR) LIKE ? OR t.status LIKE ? ORDER BY t.transaction_id DESC";return query(sql,term,term,term,term);}
 public List<Transaction> findByMember(long memberId){return query(BASE+"WHERE t.member_id=? ORDER BY t.transaction_id DESC",memberId);}
 public Transaction findById(long id){List<Transaction> x=query(BASE+"WHERE t.transaction_id=?",id);return x.isEmpty()?null:x.get(0);}
 public int activeCount(Connection c,long memberId)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM transactions WHERE member_id=? AND return_date IS NULL")){p.setLong(1,memberId);try(ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}}
 public boolean hasActiveBook(Connection c,long memberId,long bookId)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM transactions WHERE member_id=? AND book_id=? AND return_date IS NULL")){p.setLong(1,memberId);p.setLong(2,bookId);try(ResultSet r=p.executeQuery()){return r.next();}}}
 public void insert(Connection c,Transaction t)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO transactions(book_id,member_id,issue_date,due_date,return_date,fine,status) VALUES(?,?,?,?,NULL,0,'ISSUED')")){p.setLong(1,t.getBookId());p.setLong(2,t.getMemberId());p.setDate(3,java.sql.Date.valueOf(t.getIssueDate()));p.setDate(4,java.sql.Date.valueOf(t.getDueDate()));p.executeUpdate();}}
 public void returnBook(Connection c,long id,java.sql.Date date,BigDecimal fine)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE transactions SET return_date=?,fine=?,status='RETURNED' WHERE transaction_id=? AND return_date IS NULL")){p.setDate(1,date);p.setBigDecimal(2,fine);p.setLong(3,id);if(p.executeUpdate()==0)throw new SQLException("This transaction is already returned or does not exist.");}}
 public void refreshOverdue(){try(Connection c=DBConnection.getConnection();PreparedStatement a=c.prepareStatement("UPDATE transactions SET status='OVERDUE' WHERE return_date IS NULL AND due_date<CURDATE()" );PreparedStatement b=c.prepareStatement("UPDATE transactions SET status='ISSUED' WHERE return_date IS NULL AND due_date>=CURDATE()")){a.executeUpdate();b.executeUpdate();}catch(SQLException e){throw new RuntimeException("Unable to refresh overdue transactions.",e);}}
 public Map<String,Number> statistics(){String sql="SELECT (SELECT COALESCE(SUM(quantity),0) FROM books WHERE status='ACTIVE') totalBooks,(SELECT COALESCE(SUM(available_quantity),0) FROM books WHERE status='ACTIVE') availableBooks,(SELECT COUNT(*) FROM users WHERE role='MEMBER' AND status='ACTIVE') members,(SELECT COUNT(*) FROM transactions WHERE return_date IS NULL AND due_date<CURDATE()) overdue,(SELECT COALESCE(SUM(fine),0) FROM transactions) fine";Map<String,Number> out=new LinkedHashMap<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql);ResultSet r=p.executeQuery()){r.next();out.put("Total Books",r.getLong("totalBooks"));out.put("Available Copies",r.getLong("availableBooks"));out.put("Issued Copies",r.getLong("totalBooks")-r.getLong("availableBooks"));out.put("Active Members",r.getLong("members"));out.put("Overdue Books",r.getLong("overdue"));out.put("Total Fine",r.getBigDecimal("fine"));}catch(SQLException e){throw new RuntimeException("Unable to load statistics.",e);}return out;}
 private List<Transaction> query(String sql,Object... values){List<Transaction> list=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){for(int i=0;i<values.length;i++){Object v=values[i];if(v instanceof Long)p.setLong(i+1,(Long)v);else p.setString(i+1,"%"+v+"%");}try(ResultSet r=p.executeQuery()){while(r.next())list.add(map(r));}}catch(SQLException e){throw new RuntimeException("Unable to load transactions.",e);}return list;}
 private Transaction map(ResultSet r)throws SQLException{Transaction t=new Transaction();t.setTransactionId(r.getLong("transaction_id"));t.setBookId(r.getLong("book_id"));t.setMemberId(r.getLong("member_id"));t.setBookName(r.getString("book_name"));t.setMemberName(r.getString("member_name"));t.setIssueDate(r.getDate("issue_date").toLocalDate());t.setDueDate(r.getDate("due_date").toLocalDate());java.sql.Date d=r.getDate("return_date");t.setReturnDate(d==null?null:d.toLocalDate());t.setFine(r.getBigDecimal("fine"));t.setStatus(TransactionStatus.valueOf(r.getString("status")));return t;}
}
